"""Creator 6.3 candidate-generation brief with Superhuman Creator Core."""
from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PREFLIGHT=ROOT/'data/live/editorial_preflight.json'; NEWS=ROOT/'data/live/news_snapshot.json'; CONTEXT=ROOT/'data/live/publication_context.json'; CORE=ROOT/'data/live/superhuman_creator_core.json'
def load(p):
    try:
        x=json.loads(p.read_text(encoding='utf-8')); return x if isinstance(x,dict) else {}
    except Exception:return {}
def main():
    p=load(PREFLIGHT); d=p.get('content_director_4') or {}; s=p.get('script_director_4') or {}; news=load(NEWS); ctx=load(CONTEXT); core=load(CORE)
    fmt=str(d.get('recommended_format') or 'TOP MOVERS'); sym=str(ctx.get('symbol') or s.get('primary_symbol') or (d.get('primary_story') or {}).get('symbol','')).upper().replace('USDT','').replace('$','').strip(); selected=p.get('selected_opportunity') or {}; story=d.get('primary_story') or {}; narrative=str(d.get('narrative_engine') or s.get('narrative_engine') or 'what_to_watch'); archetype=str(s.get('creator_archetype') or 'conversational'); hooks=s.get('hook_candidates') or []
    if not sym: raise SystemExit('Candidate generation: authoritative asset missing')
    news_context=[]
    for article in (news.get('articles') or [])[:12]:
        if isinstance(article,dict): news_context.append({'title':article.get('title'),'source':article.get('source'),'url':article.get('url'),'published_at':article.get('published_at'),'summary':str(article.get('summary') or '')[:500],'symbols':article.get('symbols') or [],'news_score':article.get('news_score')})
    primary_news=bool(selected.get('news_title') or ctx.get('news_title'))
    directives='\n'.join('- '+str(x) for x in (core.get('generation_directives') or []))
    redteam='\n'.join('- '+str(x) for x in (core.get('red_team_questions') or []))
    standard=json.dumps(core.get('minimum_publish_standard') or {},ensure_ascii=False)
    prompt={'version':'6.3','superhuman_core_version':core.get('version','1.0'),'symbol':sym,'format':fmt,'narrative_engine':narrative,'creator_archetype':archetype,'authoritative_context':ctx,'primary_story':story,'selected_opportunity':selected,'fresh_news':news_context[:12],'instruction':f'''You are the senior editorial intelligence system for a world-class Binance Square creator. Do not behave like a headline spinner or generic crypto copywriter. Your job is to discover and communicate an original, evidence-backed insight that a serious reader would not get from a basic news recap.\n\nSUPERHUMAN CREATOR CORE DIRECTIVES:\n{directives}\n\nRED-TEAM BEFORE SELECTION:\n{redteam}\n\nMINIMUM TARGET STANDARD: {standard}\n\nFIRST: reason privately about 5 genuinely different theses, not 5 wordings of one thesis. Test which thesis contains the strongest information advantage, evidence, tension, consequence and reader usefulness.\n\nTHEN: create 5 genuinely different finished candidates about THAT story. Roles: strongest selected format; evidence/data angle; mechanism angle; counterpoint/risk angle; concise high-energy angle. At least one candidate must explain a hidden mechanism, at least one must challenge the obvious narrative, and at least one must turn the evidence into a reusable mental model.\n\nSELECTED FORMAT: {fmt}\nNARRATIVE ENGINE: {narrative}\nCREATOR ARCHETYPE: {archetype}\nPRIMARY NEWS STORY PRESENT: {str(primary_news).lower()}\n\nNEWS RULES: If news is present, state what the verified event actually says and why it matters, but do NOT merely copy the headline. The supplied verified headline may need to be retained verbatim elsewhere for integrity; do not create duplicate 'Source:' lines or awkward source boilerplate. Present attribution naturally. Never invent, paraphrase into a new factual claim, or embellish the source.\n\nCONTENT STANDARD: Every candidate must be mobile-first and contain a specific hook, the 1-3 strongest supplied facts, one non-obvious interpretation, one meaningful counterpoint or invalidation condition, a concrete 'what would confirm/change my view' signal, and exactly ONE genuine question. The question must be specific to the thesis and useful for discussion. NEVER use generic endings such as 'Bullish, bearish, or wait?', 'Which asset are you watching?', 'What do you think?', 'Agree or disagree?', or 'Thoughts?' unless the actual story makes such a question unusually informative. Prefer a question that reveals the reader's evidence, scenario, timeframe, or interpretation.\n\nHUMAN-QUALITY WRITING: Use varied sentence lengths, natural rhythm, precise verbs, selective emphasis, and a recognizable point of view. It is acceptable to sound conversational, skeptical, excited, surprised or uncertain when the evidence warrants it. Do not manufacture personal experience, trades, profits, conversations, or emotions the creator did not actually have. Avoid polished corporate filler, repetitive transitions, formulaic emoji stacks, and sterile AI phrasing.\n\nORIGINALITY TEST: A candidate that could be pasted onto another coin with only the ticker changed is an automatic failure. A candidate that only summarizes the supplied headline is an automatic failure. A candidate whose insight is obvious from the headline alone is weak. A candidate that adds a verified mechanism, relationship, comparison, contradiction, or decision framework is preferred.\n\nEVIDENCE DISCIPLINE: Use ONLY supplied verified evidence. Never invent prices, volume, sources, headlines, targets, stops, whale activity, liquidations, listings, ETF flows, macro facts, creator calls or outcomes. Never turn a hypothesis into a fact. Conditional language must stay conditional.\n\nVISUAL INTELLIGENCE: The post must make a specific request of the visual layer: identify exactly what the chart/graphic should prove or clarify (for example price-volume divergence, event timing, range compression, before/after structure, or a simple causal chain). Never request a decorative logo or generic AI image.\n\nBefore selecting the winner, aggressively red-team all five. Reject anything obvious, generic, unsupported, templated, repetitive, low-value, source-copying, or dependent on fake urgency. Select the candidate that teaches something, reveals a useful implication, or frames a decision better than the average Binance Square market post.''','selection_criteria':['information_advantage','thesis_strength','stop_scroll_strength','evidence_density','specificity','reader_value','originality','why_now clarity','usefulness','conversation_quality','mobile_readability','format_fidelity','visual_information_value','risk_discipline','anti_genericity','anti_ai_templating','natural_voice'],'hook_candidates':hooks}
    p['candidate_generation_4']=prompt; PREFLIGHT.write_text(json.dumps(p,indent=2,ensure_ascii=False),encoding='utf-8'); print(json.dumps({'status':'OK','version':'6.3','superhuman_core':'1.0','format':fmt,'symbol':sym,'candidate_count':5,'primary_news':primary_news},indent=2))
if __name__=='__main__':main()
